35	        boolean doubled = true;
36	        for (int i = value.length() - 1; i >= 0; i--) {
37	            char c = value.charAt(i);
38	            if (c < '0' || c > '9') {
39	                continue;
40	            }
41	            int d = c - '0';
42	            if (doubled) {
43	                d *= 2;
44	                if (d > 9) {
45	                    d -= 9;
46	                }
47	            }
48	            sum += d;
