63	
64	import jakarta.transaction.Transactional;
65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final OwnerFieldsValidator ownerFieldsValidator;
84	
85	    private final PostcodeValidator postcodeValidator;
86	
87	    private final HouseholdDuplicateValidator householdDuplicateValidator;
88	
89	    private final IdentityDuplicateValidator identityDuplicateValidator;
90	
91	    private final HouseholdIdGenerator householdIdGenerator;
92	
93	    private final TelephoneNormalizer telephoneNormalizer;
94	
95	    private final EmailNormalizer emailNormalizer;
96	
97	    private final AddressNormalizer addressNormalizer;
98	
99	    private final CustomerCodeGenerator customerCodeGenerator;
100	
101	    private final NamesakeCounter namesakeCounter;
102	
103	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
104	
105	    private final OwnerAuditLogger ownerAuditLogger;
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper,
111	                                 OwnerFieldsValidator ownerFieldsValidator,
112	                                 PostcodeValidator postcodeValidator,
113	                                 HouseholdDuplicateValidator householdDuplicateValidator,
114	                                 IdentityDuplicateValidator identityDuplicateValidator,
115	                                 HouseholdIdGenerator householdIdGenerator,
116	                                 TelephoneNormalizer telephoneNormalizer,
117	                                 EmailNormalizer emailNormalizer,
118	                                 AddressNormalizer addressNormalizer,
119	                                 CustomerCodeGenerator customerCodeGenerator,
120	                                 NamesakeCounter namesakeCounter,
121	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
122	                                 OwnerAuditLogger ownerAuditLogger) {
123	        this.clinicService = clinicService;
124	        this.ownerMapper = ownerMapper;
125	        this.petMapper = petMapper;
126	        this.visitMapper = visitMapper;
127	        this.ownerFieldsValidator = ownerFieldsValidator;
128	        this.postcodeValidator = postcodeValidator;
129	        this.householdDuplicateValidator = householdDuplicateValidator;
130	        this.identityDuplicateValidator = identityDuplicateValidator;
131	        this.householdIdGenerator = householdIdGenerator;
132	        this.telephoneNormalizer = telephoneNormalizer;
133	        this.emailNormalizer = emailNormalizer;
134	        this.addressNormalizer = addressNormalizer;
135	        this.customerCodeGenerator = customerCodeGenerator;
136	        this.namesakeCounter = namesakeCounter;
137	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
138	        this.ownerAuditLogger = ownerAuditLogger;
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
169	        if (ownerFieldsDto != null) {
170	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
171	        }
172	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
173	        if (!missingFields.isEmpty()) {
174	            throw new MissingOwnerFieldsException(missingFields);
175	        }
176	        HttpHeaders headers = new HttpHeaders();
177	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
178	        Collection<Owner> sameLastName =
179	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
180	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
181	        List<Owner> householdMembers = assignHousehold(owner, ownerFieldsDto, sameLastName);
182	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
183	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
184	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
185	        rejectIfDuplicateIdentity(owner);
186	        joinHousehold(owner, householdMembers);
187	        if (owner.getRegistrationDate() == null) {
188	            owner.setRegistrationDate(LocalDate.now());
189	        }
190	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
191	        LocalDate registrationDate = owner.getRegistrationDate();
192	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
193	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
194	            throw new DailyOwnerLimitException(registrationDate);
195	        }
196	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
197	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
198	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
199	            throw new CityOwnerLimitException(owner.getCity());
200	        }
201	        owner.setCustomerCode(customerCodeGenerator.generate(
202	            owner.getCity(), owner.getLastName(), cityOwnerCount));
203	        this.clinicService.saveOwner(owner);
204	        ownerAuditLogger.ownerCreated(owner);
205	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
206	        headers.setLocation(UriComponentsBuilder.newInstance()
207	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
208	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
209	    }
210	
211	    /**
212	     * Assigns the household attributes of an owner about to be created, without touching any
213	     * existing owner. The new owner's household size after this create is recorded (the existing
214	     * members that share its last name and address, compared case-insensitively with collapsed
215	     * whitespace, plus the owner itself). When the owner shares a household with an existing one
216	     * and the request opted in via {@code sharesHousehold}, the new owner is stamped with the
217	     * household's stable {@code householdId}.
218	     *
219	     * <p>Sharing a household is no longer a rejection in itself: duplicate detection is decided
220	     * solely by the derived identity key in {@link #rejectIfDuplicateIdentity(Owner)}. Because the
221	     * telephone is part of that key, household members with different telephones are all allowed.
222	     *
223	     * @return the existing household members that the new owner joins (empty when it starts a new
224	     *         household or does not opt in)
225	     */
226	    private List<Owner> assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto, Collection<Owner> sameLastName) {
227	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
228	        owner.setHouseholdSize(members.size() + 1);
229	        if (members.isEmpty() || !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
230	            return List.of();
231	        }
232	        owner.setHouseholdId(householdIdGenerator.generate(owner));
233	        return members;
234	    }
235	
236	    /**
237	     * Stamps every existing member the new owner joins with the owner's {@code householdId}, so
238	     * the whole household shares one identifier. Called only once the owner has cleared duplicate
239	     * detection, so no existing owner is mutated for a create that is going to be rejected.
240	     */
241	    private void joinHousehold(Owner owner, List<Owner> members) {
242	        String householdId = owner.getHouseholdId();
243	        for (Owner member : members) {
244	            if (!householdId.equals(member.getHouseholdId())) {
245	                member.setHouseholdId(householdId);
246	                this.clinicService.saveOwner(member);
247	            }
248	        }
249	    }
250	
251	    /**
252	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
253	     * owner. A full-key match requires an equal telephone, so only owners with the same
254	     * (already normalized) telephone are compared.
255	     *
256	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
257	     */
258	    private void rejectIfDuplicateIdentity(Owner owner) {
259	        Collection<Owner> sameTelephone = this.clinicService.findOwnersByTelephone(owner.getTelephone());
260	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
261	            throw new DuplicateIdentityException(IdentityKey.of(owner));
262	        }
263	    }
264	
265	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
266	    @Override
267	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
268	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
269	        if (currentOwner == null) {
270	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	        }
272	        currentOwner.setAddress(ownerFieldsDto.getAddress());
273	        currentOwner.setCity(ownerFieldsDto.getCity());
274	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
275	        currentOwner.setLastName(ownerFieldsDto.getLastName());
276	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
277	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
278	        this.clinicService.saveOwner(currentOwner);
279	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
280	    }
281	
282	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
283	    @Transactional
284	    @Override
285	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
286	        Owner owner = this.clinicService.findOwnerById(ownerId);
287	        if (owner == null) {
288	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
289	        }
290	        this.clinicService.deleteOwner(owner);
291	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
292	    }
293	
294	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
295	    @Override
296	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
297	        Owner owner = this.clinicService.findOwnerById(ownerId);
298	        if (owner == null) {
299	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
300	        }
301	        HttpHeaders headers = new HttpHeaders();
302	        Pet pet = petMapper.toPet(petFieldsDto);
303	        owner.setId(ownerId);
304	        pet.setOwner(owner);
305	        pet.getType().setName(null);
306	        this.clinicService.savePet(pet);
307	        PetDto petDto = petMapper.toPetDto(pet);
308	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
309	            .buildAndExpand(pet.getId()).toUri());
310	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
311	    }
312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Override
315	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
316	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
317	        if (currentOwner != null) {
318	            Pet currentPet = this.clinicService.findPetById(petId);
319	            if (currentPet != null) {
320	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
321	                currentPet.setName(petFieldsDto.getName());
322	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
323	                this.clinicService.savePet(currentPet);
324	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
325	            }
326	        }
327	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
328	    }
329	
330	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
331	    @Override
332	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
333	        HttpHeaders headers = new HttpHeaders();
334	        Visit visit = visitMapper.toVisit(visitFieldsDto);
335	        Pet pet = new Pet();
336	        pet.setId(petId);
337	        visit.setPet(pet);
338	        this.clinicService.saveVisit(visit);
339	        VisitDto visitDto = visitMapper.toVisitDto(visit);
340	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
341	            .buildAndExpand(visit.getId()).toUri());
342	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
343	    }
344	
345	
346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
349	        Owner owner = this.clinicService.findOwnerById(ownerId);
350	        if (owner != null) {
351	            Pet pet = owner.getPet(petId);
352	            if (pet != null) {
353	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
354	            }
355	        }
356	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
357	    }
358	}
